import './index.less'
import { CountDownBanner } from './sections/index-countdown-banner'
import { VideoBanner } from './sections/index-video-banner'
import { ProductsSwiper } from './sections/index-new-product'
import { SceneEducation } from './sections/index-scene-education'
import { StoriesSwiper } from './sections/index-stories'
import { IndexNewGAEvent } from "./sections/index-new-ga"
import { RegularBanner } from "./sections/index-regular-banner"

$(document).ready(function() {
    new RegularBanner(document.querySelector('.index-regular-banner .swiper-container'))
    $('.index-function-banner').each(function () {
        const clas = $(this).data('name');
        if (!clas) return;

        const $el = $(`.${clas}`);
        const type = $el.data('type');

        // 使用全局懒执行函数
        lazyInit($el[0], () => {
            if (type === 'countdown') {
            new CountDownBanner({ el: $el, clas });
            } else if (type === 'video') {
            new VideoBanner({ el: $el, clas });
            }
        });
    });

    $('.index-new-products').each(function () {
        const clas = $(this).data('name');
        if (!clas) return;

        const $el = $(`.${clas}`);
        if (!$el.length) return;

        // 懒执行初始化
        lazyInit($el[0], () => {
            new ProductsSwiper({ el: $el, clas });
        });
    });
    lazyInit('.index-scene-education', () => new SceneEducation())

    if(window.innerWidth < 1024){
        // 仅移动端 轮播展示
        lazyInit('.stories-swiper', () => new StoriesSwiper())
    }

    IndexNewGAEvent()

   // 渐变出现
   const observer = new IntersectionObserver((entries) => {
        entries.forEach((entry) => {
            if (entry.isIntersecting) {
            // 元素进入视窗,触发动画
            entry.target.classList.add('jky-slideup-animate');
            }
        });
    });

    // 开始观察目标元素
    const slideups = document.querySelectorAll('.jky-slideup')
    if (slideups && slideups.length) {
        slideups.forEach(item => {
            observer.observe(item);
        })
    }
})